/** Surah ids that appear on a mushaf page (usually 1, sometimes 2). */
export function surahsOnMushafPage(page: number): number[] {
  const ids: number[] = [];
  for (let id = 1; id <= 114; id++) {
    if (page >= SURAH_FIRST_PAGE[id] && page <= SURAH_LAST_PAGE[id]) ids.push(id);
  }
  return ids;
}

